        readonly Report report=new Report();PlanetDevelopment world;string output;RenderTexture captureTarget;
        Color32[] Capture(string name){if(captureTarget==null){captureTarget=new RenderTexture(2560,1440,24,RenderTextureFormat.ARGBHalf);captureTarget.Create();world.View.enabled=false;world.View.targetTexture=captureTarget;}RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=captureTarget});var previous=RenderTexture.active;RenderTexture.active=captureTarget;var image=new Texture2D(captureTarget.width,captureTarget.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,captureTarget.width,captureTarget.height),0,0);image.Apply();var pixels=image.GetPixels32();int lit=0;foreach(var pixel in pixels)if(pixel.r>10||pixel.g>10||pixel.b>10)lit++;Check(lit>1000,name+" renders visible scene pixels in the hidden standalone player");File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=previous;return pixels;}
        void LateUpdate(){if(captureTarget!=null)RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=captureTarget});}
        float Difference(Color32[] a,Color32[] b){double total=0;for(int i=0;i<a.Length;i++)total+=Math.Abs(a[i].r-b[i].r)+Math.Abs(a[i].g-b[i].g)+Math.Abs(a[i].b-b[i].b);return (float)(total/(a.Length*765.0));}
        void OnDestroy(){if(captureTarget!=null){captureTarget.Release();Destroy(captureTarget);}}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-gameplay-validation")>=0)new GameObject("Planet gameplay validation").AddComponent<PlanetGameplayValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-planet-output");output=args[i+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.sessionMode=PlanetGameMode.AiTest;world.ambientZombies=512;world.requestedCapacity=8192;world.configuredRadius=120000;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Time.captureDeltaTime=BattleSettings.Tick;}
