        IEnumerator Run(){while(!world.Ready||world.EncounterForValidation==null)yield return null;world.Rig.InputEnabled=false;world.FocusFaction(0);var hd=world.View.GetComponent<UnityEngine.Rendering.HighDefinition.HDAdditionalCameraData>();hd.antialiasing=UnityEngine.Rendering.HighDefinition.HDAdditionalCameraData.AntialiasingMode.None;yield return null;
            Check(world.StrategyEnabled&&world.definition.radius==120000,"Actual 120 km AI Test uses autonomous factions");
            for(int team=0;team<2;team++){int t=team;Check(world.Base.Buildings.Count(b=>b.team==t&&b.Complete)>=4,"Faction "+team+" owns a complete starter base");Check(world.Base.Buildings.Any(b=>b.team==t&&b.definition.id=="command"),"Faction "+team+" has its own command centre");}
