            while(world.SimulationTicks<30)yield return null;var initial=new UnitState[world.unitCount];world.UnitsForValidation.GetData(initial);Check(initial.Any(u=>(u.flags&1)!=0&&(u.packed&255)==0)&&initial.Any(u=>(u.flags&1)!=0&&(u.packed&255)==1),"Both regular factions have live GPU army records");
            foreach(var u in initial.Where(u=>(u.packed&255)==2&&(u.flags&1)!=0))foreach(var home in world.Base.Homes)Check(Vector3.Distance(CubeSphere.Decode(u.position),home)*world.definition.radius>=1495,"Ambient spawn clears both initial bases");
            // Use one aggregate check rather than logging hundreds of identical successes.
