                for(int i=0;i<samples.Length;i++){var u=samples[i];if((u.flags&1)==0||(u.packed&255)!=2)continue;if(u.target!=uint.MaxValue){stimulated[i]=true;continue;}
                    var goal=CubeSphere.Decode(u.destination);if(CubeSphere.ArcDistance(goal,CubeSphere.Decode(origins[i]),world.definition.radius)>100){var cell=CubeSphere.Cell(world.definition.bodyId,goal,world.navigationResolution);if(CubeSphere.ArcDistance(goal,CubeSphere.Direction(cell,world.navigationResolution),world.definition.radius)<.5f)stimulated[i]=true;}
                }}yield return null;}world.Paused=true;var records=new UnitState[world.unitCount];world.UnitsForValidation.GetData(records);
            bool refuge=true,tether=true;int moving=0;for(int i=0;i<records.Length;i++){var u=records[i];if((u.flags&1)==0||(u.packed&255)!=2)continue;var d=CubeSphere.Decode(u.position);foreach(var home in world.Base.Homes)refuge&=Vector3.Distance(d,home)*world.definition.radius>=1494;if(i<origins.Length){if(stimulated[i])report.stimulatedZombies++;else if(u.target==uint.MaxValue){report.unstimulatedZombies++;float drift=Vector3.Distance(d,CubeSphere.Decode(origins[i]))*world.definition.radius;report.maximumUnstimulatedDrift=Mathf.Max(report.maximumUnstimulatedDrift,drift);tether&=drift<100;}}if(u.velocity.sqrMagnitude>.1f)moving++;}
            Check(refuge,"No ambient zombie enters either starting refuge during AI preparation");Check(tether&&report.unstimulatedZombies>=32,"At least 32 zombies without observed combat or noise stimulation remain within their bounded home ranges after 130 simulated seconds");Check(moving>0,"Zombies continue moving while home ranges are bounded");
            report.decisions=world.Base.AIDecisions;report.buildings=new[]{world.Base.Buildings.Count(b=>b.team==0),world.Base.Buildings.Count(b=>b.team==1)};report.health=world.Base.Buildings.Where(b=>b.definition.id=="command").Select(b=>b.health).ToArray();
            Check(report.health.Length==2&&report.health.Zip(commandHealth,(a,b)=>a>=b).All(x=>x),"Both command centres survive AI startup without zombie damage");
            for(int team=0;team<2;team++){int t=team;Check(report.decisions[team]>20,"Faction "+team+" repeatedly makes AI decisions");Check(report.buildings[team]>4,"Faction "+team+" constructs additional infrastructure");Check(world.Base.Buildings.Any(b=>b.team==t&&b.node>=0),"Faction "+team+" establishes resource extraction");Check(records.Count(u=>(u.flags&1)!=0&&(u.packed&255)==t)>32,"Faction "+team+" produces reinforcements");Check(world.Base.Factions[team].technologies.Count>0||world.Base.Factions[team].researching.Count>0,"Faction "+team+" researches catalogue technologies");}
            Capture("faction-one");yield return new WaitForEndOfFrame();world.Rig.SetFocusDirection(world.Base.Homes[1]);world.Rig.Step();yield return null;Capture("faction-two");yield return new WaitForEndOfFrame();
            var ship=world.ShipForValidation;Check(ship!=null,"Capital ship exists in the playable session");var start=ship.Pose;Check(ship.TakeOff(),"Space takeoff releases the parked ship");for(int step=0;step<900&&ship.AutoFlightActive;step++)ship.Integrate(1f/60,Vector3.zero,Vector3.zero);ship.SetFlightAssistance(false);for(int i=0;i<60;i++)ship.Integrate(1f/60,Vector3.up,Vector3.zero);Check(ship.Speed>10&&ship.Pose.position.Magnitude>start.position.Magnitude+5,"Capital ship lifts off using its own double-precision pose");double speed=ship.Speed;ship.Integrate(.1f,Vector3.zero,Vector3.zero);Check(ship.Speed>speed*.7,"Ship retains inertia when thrust is released");var frame=ship.Frames.Resolve(new SpacePose{frameId=1,rotation=Quaternion.identity,position=new Double3(0,15,30)});Check(frame.position.RelativeTo(world.definition.position).Magnitude>world.definition.radius,"Ship-local cockpit resolves to universe coordinates");world.SetShipControl(true);Check(world.IsPiloting,"Control ownership transfers to ship");world.Paused=false;yield return null;world.Paused=true;Check(world.View.transform.position.magnitude<2100,"Ship camera participates in floating-origin rebasing");Capture("ship-cockpit");yield return new WaitForEndOfFrame();world.SetFirstPerson(false);Check(!world.IsPiloting,"Leaving ship control through the FPS/RTS switch restores RTS safely");var unpiloted=ship.Pose.position;world.Paused=false;for(int i=0;i<6;i++)yield return null;world.Paused=true;Check((ship.Pose.position-unpiloted).Magnitude>.1,"Unpiloted airborne ship continues physical motion while RTS controls the camera");world.Rig.SetFocusDirection(ship.Direction);world.Rig.Distance=180;world.Rig.Step();yield return null;var withShip=Capture("ship-from-base");ship.VisualForValidation.SetActive(false);yield return null;var withoutShip=Capture("without-ship");Check(Difference(withShip,withoutShip)>.001f,"The physical capital ship visibly renders in the external RTS view");ship.VisualForValidation.SetActive(true);yield return new WaitForEndOfFrame();
            var impact=world.Base.Offset(new Vector2(0,500));var pair=new[]{new UnitState{position=CubeSphere.Encode(impact),health=1000,flags=1,packed=2u|(31u<<8),target=uint.MaxValue},new UnitState{position=CubeSphere.Encode(world.Base.Offset(new Vector2(0,800))),health=1000,flags=1,packed=2u|(31u<<8),target=uint.MaxValue}};world.UnitsForValidation.SetData(pair,0,0,2);uint stamps=world.EncounterForValidation.DecalCountForValidation;world.EncounterForValidation.Detonate(impact);world.UnitsForValidation.GetData(pair,0,0,2);Check(pair[0].health==0&&pair[1].health==1000,"Nuke applies radial GPU damage while paused and preserves an outside-radius unit");Check(world.EncounterForValidation.DecalCountForValidation>stamps,"Nuke writes an original crater layer to persistent planetary surface paint");Check(world.EncounterForValidation.NukesDetonated==1,"One nuke request creates one detonation");world.Rig.SetFocusDirection(impact);world.Rig.Distance=500;world.Rig.Step();yield return null;yield return null;foreach(var effect in FindObjectsByType<VisualEffect>(FindObjectsSortMode.None))if(effect.visualEffectAsset.name=="NuclearBurst")effect.Simulate(.1f,100);yield return null;var cloud=FindObjectsByType<VisualEffect>(FindObjectsSortMode.None).First(e=>e.visualEffectAsset.name=="NuclearBurst");report.nukeParticles=cloud.aliveParticleCount;report.nukeCulled=cloud.culled;var withCloud=Capture("nuke");cloud.gameObject.SetActive(false);yield return null;var withoutCloud=Capture("without-cloud");var systems=new List<string>();cloud.GetParticleSystemNames(systems);Check(systems.Count==5,"Original nuclear graph retains its five cloud, stem, dust, flash and shockwave systems");Check(Difference(withCloud,withoutCloud)>.0001f,"Original nuclear cloud visibly renders above the spherical terrain");cloud.gameObject.SetActive(true);yield return new WaitForEndOfFrame();Check(!world.TryTestNukeAtCursor(new Vector2(5,Screen.height-5)),"N-key handler ignores original HUD controls");
            var faction=world.Base.Faction;faction.tier=5;faction.technologies.Add("nuclear");faction.wallet.Capacity=new ResourceCost{materials=10000,fuel=10000,rareElements=10000,isotopes=10000,research=10000};faction.wallet.Stock=faction.wallet.Capacity;
            bool built=false;for(int i=0;i<96&&!built;i++){float angle=i*Mathf.PI/16,range=100+i/32*40;built=world.Base.ConstructForTeam("silo",0,world.Base.Offset(new Vector2(-65+Mathf.Cos(angle)*range,-55+Mathf.Sin(angle)*range)));}Check(built,"A catalogue nuclear silo can be constructed through planetary placement");var silo=world.Base.Buildings.Last();silo.construction=silo.definition.time;float fuel=faction.wallet.Stock.fuel,isotopes=faction.wallet.Stock.isotopes;Check(world.EncounterForValidation.LaunchNuke(silo,impact),"A completed nuclear silo accepts an in-range strategic target");Check(faction.wallet.Stock.fuel==fuel-100&&faction.wallet.Stock.isotopes==isotopes-25,"Silo launch consumes fuel and isotopes");Check(!world.EncounterForValidation.LaunchNuke(silo,impact),"Silo cooldown rejects a duplicate launch");world.Paused=false;uint impactTick=world.SimulationTicks+362;while(world.SimulationTicks<impactTick)yield return null;world.Paused=true;Check(world.EncounterForValidation.NukesDetonated==2,"Paid nuclear missile detonates after its twelve-second simulation delay");world.sessionMode=PlanetGameMode.Rts;world.Paused=false;var enemyCommand=world.Base.Buildings.First(b=>b.team==1&&b.definition.id=="command");world.Base.Damage(enemyCommand,1000000);Check(world.Paused&&world.Base.Outcome.Contains("VICTORY"),"Destroying the enemy command centre resolves normal RTS victory");
